// wf.match.tool_search > "Profile input": the agent's request goes through P2 (wf.profile.extract), like a search
// typed by the user, so the same checks apply (allowed preferences, currencies, geocoding).
const s = $('Start').first().json;
return [{ json: { text: String(s.request || '').slice(0, 2000), jurisdiction: s.jurisdiction, today: s.today } }];

// wf.match.tool_search > "Search plan": search filters from the profile P2 read in the agent's request.
const s = $('Start').first().json;
const x = $input.first().json;
if (!x.ok) return [{ json: { skip: true } }];
const p = x.profile;
const a = x.anchor && x.anchor.status === 'found' ? x.anchor.place : null;
return [{ json: { skip: false, jurisdiction: x.search_jurisdiction || s.jurisdiction, q: String(s.request || '').slice(0, 2000),
  max_rent_minor: p.budget_max_minor, currency: p.currency, budget_period: p.budget_period,
  lat: a ? a.lat : null, lng: a ? a.lng : null, place: null, radius_m: null, limit: 10 } }];

// wf.match.tool_search > "Session data": what is kept for the conversation (ids, understood profile, trace steps).
const s = $('Start').first().json;
const x = $('Extract profile').first().json;
let m = null;
try { m = $('Match').first().json; } catch (e) { m = null; }
const steps = [...(x.steps || [])];
if (m) steps.push({ agent: 'A3_match', model: m.applied && m.applied.vector ? 'bge-m3' : null, input: { mode: m.mode },
  output: { count: m.count, warnings: m.warnings }, latency_ms: m.timings ? m.timings.total_ms : null,
  tool_calls: [{ tool: 'app.search_public', db_ms: m.timings && m.timings.db_ms, embed_ms: m.timings && m.timings.embed_ms }] });
const results = m && m.ok ? (m.results || []).map((r) => ({ id: r.id, distance_m: r.distance_m ?? null, score: r.score ?? null })) : [];
return [{ json: { params: [s.session_id, s.user_id, s.request_id, JSON.stringify({
  results, profile: x.ok ? x.profile : null, anchor: x.ok ? x.anchor : null, steps })] } }];

// wf.match.tool_search > "Tool answer": what the model sees. Fields only, never the owner's title or description
// (spec 8.2 A3 guardrail: listing prose could carry instructions). Numbers in main units.
const x = $('Extract profile').first().json;
let m = null;
try { m = $('Match').first().json; } catch (e) { m = null; }
if (!x.ok) return [{ json: { found: 0, error: 'could_not_read_request', results: [] } }];
if (!m || !m.ok) return [{ json: { found: 0, error: 'search_failed', results: [] } }];
const p = x.profile || {};
const unit = (v, e) => (v == null ? null : Number((v / 10 ** (e ?? 2)).toFixed(e ?? 2)));
const exp = { TND: 3 }[p.currency] ?? 2;
const understood = { budget_max: unit(p.budget_max_minor, exp), currency: p.currency || null, period: p.budget_period || null,
  near: x.anchor && x.anchor.status === 'found' ? (x.anchor.place.name || x.anchor.place.label || null) : (p.anchor_label || null),
  near_found: !!(x.anchor && x.anchor.status === 'found'), move_in_from: p.move_in_from || null };
const results = (m.results || []).slice(0, 10).map((r, i) => {
  const rent = r.rent || {};
  return { number: i + 1, kind: r.kind, rent: unit(rent.amount_minor, rent.exponent), currency: rent.currency || null,
    period: rent.period || null, bills_included: r.bills_included ?? null, furnished: r.furnished ?? null,
    neighbourhood: r.neighbourhood || null, city: r.city || null,
    distance_km: r.distance_m != null ? Number((Number(r.distance_m) / 1000).toFixed(1)) : null,
    available_from: r.available_from || null };
});
return [{ json: { found: m.count ?? results.length, understood, results } }];
